"""FastAPI app factory for the REQ-002 auth seam."""

from __future__ import annotations

import logging
from typing import Any
from uuid import uuid4

from fastapi import FastAPI, Request

from backend.auth.session_rbac.router import router
from backend.shared.authz.logging import (
    build_auth_log_context,
    build_auth_log_event,
    build_header_snapshot,
)
from backend.shared.authz.settings import AuthSettings

AUTH_LOGGER = logging.getLogger("zen.auth")


def create_app(settings: AuthSettings | None = None) -> FastAPI:
    """Create an auth-focused FastAPI app.

    The service expects a trusted upstream gateway or middleware to validate
    OIDC/SAML assertions and forward normalized claims through the configured
    assertion header.
    """
    app = FastAPI(title="Zen 2030 Auth Session RBAC", version="0.1.0")
    app.state.auth_settings = settings or AuthSettings.from_env()
    app.state.last_auth_event = None
    app.include_router(router)

    @app.middleware("http")
    async def emit_structured_auth_log(request: Request, call_next):
        response = None
        try:
            response = await call_next(request)
            return response
        finally:
            active_settings: AuthSettings = request.app.state.auth_settings
            auth_log_context = _resolve_auth_log_context(request, active_settings)
            auth_event = build_auth_log_event(
                auth_log_context=auth_log_context,
                method=request.method,
                path=request.url.path,
                status_code=response.status_code if response is not None else 500,
                deny_reason=getattr(request.state, "auth_denied_reason", None),
                headers=build_header_snapshot(request.headers, active_settings),
            )
            request.app.state.last_auth_event = auth_event
            AUTH_LOGGER.info("auth.request", extra={"auth_event": auth_event})

    @app.get("/auth/_health", tags=["auth"])
    def auth_health() -> dict[str, str]:
        active_settings: AuthSettings = app.state.auth_settings
        return {
            "status": "ok",
            "runtime_profile": active_settings.runtime_profile.value,
            "auth_protocol": active_settings.auth_protocol.value,
        }

    return app


def _resolve_auth_log_context(request: Request, settings: AuthSettings) -> dict[str, Any]:
    existing = getattr(request.state, "auth_log_context", None)
    if isinstance(existing, dict) and "request_id" in existing:
        return existing

    request_id = request.headers.get(settings.request_id_header) or str(uuid4())
    return build_auth_log_context(
        request_id=request_id,
        runtime_profile=settings.runtime_profile,
        auth_protocol=settings.auth_protocol,
        actor=None,
    )


app = create_app()
