"""Runtime-configurable auth settings for REQ-002."""

from __future__ import annotations

import json
import os
from functools import lru_cache
from typing import Iterable

from pydantic import BaseModel, ConfigDict, Field

from backend.shared.authz.models import ALL_PERMISSIONS, AuthProtocol, Permission, RuntimeProfile

DEFAULT_GROUP_PERMISSION_MAP: dict[str, list[str]] = {
    "operators": [
        Permission.AUTH_SESSION_READ.value,
        Permission.DOCUMENT_UPLOAD.value,
        Permission.WORKFLOW_READ.value,
        Permission.DOCUMENT_VALIDATE.value,
        Permission.ARCHIVE_SEARCH.value,
        Permission.DOCUMENT_DOWNLOAD.value,
    ],
    "reviewers": [
        Permission.AUTH_SESSION_READ.value,
        Permission.WORKFLOW_READ.value,
        Permission.DOCUMENT_VALIDATE.value,
        Permission.ARCHIVE_SEARCH.value,
        Permission.DOCUMENT_DOWNLOAD.value,
    ],
    "exporters": [
        Permission.AUTH_SESSION_READ.value,
        Permission.DOCUMENT_EXPORT.value,
    ],
    "ai-users": [
        Permission.AUTH_SESSION_READ.value,
        Permission.DOCUMENT_AI_QUERY.value,
    ],
    "admins": sorted(ALL_PERMISSIONS),
}


class AuthSettings(BaseModel):
    """Settings shared by local and target runtime profiles."""

    model_config = ConfigDict(frozen=True)

    runtime_profile: RuntimeProfile = RuntimeProfile.LOCAL
    auth_protocol: AuthProtocol = AuthProtocol.OIDC
    assertion_header: str = "x-zen-auth-claims"
    request_id_header: str = "x-request-id"
    groups_claim_name: str = "groups"
    roles_claim_name: str = "roles"
    permissions_claim_name: str = "permissions"
    group_permission_map: dict[str, list[str]] = Field(default_factory=lambda: dict(DEFAULT_GROUP_PERMISSION_MAP))
    sensitive_headers: frozenset[str] = frozenset(
        {
            "authorization",
            "cookie",
            "x-amzn-oidc-data",
            "x-amzn-oidc-accesstoken",
            "x-forwarded-access-token",
            "x-zen-auth-claims",
        }
    )

    @property
    def resolved_sensitive_headers(self) -> frozenset[str]:
        return frozenset(
            {
                *(header.lower() for header in self.sensitive_headers),
                self.assertion_header.lower(),
            }
        )

    @classmethod
    def from_env(cls) -> "AuthSettings":
        raw_map = os.getenv("ZEN_AUTH_GROUP_PERMISSION_MAP_JSON")
        group_permission_map = _load_group_permission_map(raw_map)
        return cls(
            runtime_profile=os.getenv("ZEN_RUNTIME_PROFILE", RuntimeProfile.LOCAL.value),
            auth_protocol=os.getenv("ZEN_AUTH_PROTOCOL", AuthProtocol.OIDC.value),
            assertion_header=os.getenv("ZEN_AUTH_ASSERTION_HEADER", "x-zen-auth-claims"),
            request_id_header=os.getenv("ZEN_AUTH_REQUEST_ID_HEADER", "x-request-id"),
            groups_claim_name=os.getenv("ZEN_AUTH_GROUPS_CLAIM", "groups"),
            roles_claim_name=os.getenv("ZEN_AUTH_ROLES_CLAIM", "roles"),
            permissions_claim_name=os.getenv("ZEN_AUTH_PERMISSIONS_CLAIM", "permissions"),
            group_permission_map=group_permission_map,
        )


def _load_group_permission_map(raw_map: str | None) -> dict[str, list[str]]:
    if not raw_map:
        return dict(DEFAULT_GROUP_PERMISSION_MAP)

    parsed = json.loads(raw_map)
    if not isinstance(parsed, dict):
        raise ValueError("ZEN_AUTH_GROUP_PERMISSION_MAP_JSON must be a JSON object")

    normalized: dict[str, list[str]] = {}
    for group_name, permissions in parsed.items():
        if not isinstance(group_name, str):
            raise ValueError("group names must be strings")
        if not isinstance(permissions, list):
            raise ValueError(f"permissions for group '{group_name}' must be a list")
        normalized[group_name] = _normalize_permission_names(permissions, group_name=group_name)

    return normalized


def _normalize_permission_names(
    permission_values: Iterable[object],
    *,
    group_name: str,
) -> list[str]:
    normalized: list[str] = []
    seen: set[str] = set()
    unknown: list[str] = []

    for permission in permission_values:
        value = str(permission).strip()
        if not value:
            continue
        if value not in ALL_PERMISSIONS:
            unknown.append(value)
            continue
        if value not in seen:
            seen.add(value)
            normalized.append(value)

    if unknown:
        raise ValueError(
            f"group '{group_name}' contains unknown permissions: {', '.join(sorted(unknown))}"
        )

    return sorted(normalized)


@lru_cache(maxsize=1)
def load_auth_settings() -> AuthSettings:
    return AuthSettings.from_env()
