"""Claim normalization utilities for REQ-002."""

from __future__ import annotations

import json
from json import JSONDecodeError
from typing import Any, Mapping

from backend.shared.authz.models import ALL_PERMISSIONS, ActorContext
from backend.shared.authz.settings import AuthSettings


class AuthenticationRequiredError(Exception):
    """Raised when no valid trusted identity assertion is available."""


def parse_actor_from_headers(headers: Mapping[str, str], settings: AuthSettings) -> ActorContext:
    """Parse and normalize the trusted claims header into an ActorContext."""
    raw_claims = _get_header_value(headers, settings.assertion_header)
    if not raw_claims:
        raise AuthenticationRequiredError("missing trusted identity assertion header")

    try:
        payload = json.loads(raw_claims)
    except JSONDecodeError as exc:
        raise AuthenticationRequiredError("malformed trusted identity assertion header") from exc

    if not isinstance(payload, dict):
        raise AuthenticationRequiredError("trusted identity assertion must be a JSON object")

    return normalize_identity_claims(payload, settings)


def normalize_identity_claims(payload: Mapping[str, Any], settings: AuthSettings) -> ActorContext:
    """Normalize OIDC-style or SAML-style claims into one stable actor model."""
    actor_id = _first_text(payload, "sub", "name_id", "user_id", "uid")
    if not actor_id:
        raise AuthenticationRequiredError("trusted identity assertion missing subject")

    username = _first_text(payload, "preferred_username", "username", "email") or actor_id
    display_name = _first_text(payload, "display_name", "name", "full_name", "cn") or username
    active = _coerce_bool(payload.get("active"), default=True)

    groups = set(_as_list(payload.get(settings.groups_claim_name)))
    groups.update(_as_list(payload.get(settings.roles_claim_name)))

    permissions = set(_known_permissions(_as_list(payload.get(settings.permissions_claim_name))))
    for group_name in groups:
        permissions.update(settings.group_permission_map.get(group_name, []))

    return ActorContext(
        id=actor_id,
        username=username,
        display_name=display_name,
        active=active,
        permissions=frozenset(sorted(permissions)),
        groups=frozenset(sorted(groups)),
    )


def _get_header_value(headers: Mapping[str, str], header_name: str) -> str | None:
    direct_value = headers.get(header_name)
    if direct_value is not None:
        return direct_value

    target = header_name.lower()
    for key, value in headers.items():
        if key.lower() == target:
            return value
    return None


def _first_text(payload: Mapping[str, Any], *keys: str) -> str | None:
    for key in keys:
        value = payload.get(key)
        if isinstance(value, str):
            candidate = value.strip()
            if candidate:
                return candidate
    return None


def _as_list(value: Any) -> list[str]:
    if value is None:
        return []
    if isinstance(value, str):
        return [item.strip() for item in value.split(",") if item.strip()]
    if isinstance(value, list):
        normalized: list[str] = []
        for item in value:
            candidate = str(item).strip()
            if candidate:
                normalized.append(candidate)
        return normalized
    candidate = str(value).strip()
    return [candidate] if candidate else []


def _known_permissions(values: list[str]) -> list[str]:
    return [value for value in values if value in ALL_PERMISSIONS]


def _coerce_bool(value: Any, *, default: bool) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"true", "1", "yes", "y"}:
            return True
        if normalized in {"false", "0", "no", "n"}:
            return False
    return default
