"""Structured auth logging helpers for REQ-002."""

from __future__ import annotations

from typing import Mapping

from backend.shared.authz.models import ActorContext, AuthProtocol, RuntimeProfile
from backend.shared.authz.settings import AuthSettings


def sanitize_headers(headers: Mapping[str, str], sensitive_headers: set[str] | frozenset[str]) -> dict[str, str]:
    """Return a lower-cased header map with sensitive values redacted."""
    sensitive = {header.lower() for header in sensitive_headers}
    sanitized: dict[str, str] = {}
    for key, value in headers.items():
        normalized_key = key.lower()
        sanitized[normalized_key] = "[REDACTED]" if normalized_key in sensitive else value
    return sanitized


def build_header_snapshot(headers: Mapping[str, str], settings: AuthSettings) -> dict[str, str]:
    """Return a minimal, redacted auth-relevant header snapshot."""
    interesting_headers = {
        "authorization",
        "cookie",
        "x-amzn-oidc-data",
        "x-amzn-oidc-accesstoken",
        "x-forwarded-access-token",
        settings.assertion_header.lower(),
        settings.request_id_header.lower(),
    }
    sanitized = sanitize_headers(headers, settings.resolved_sensitive_headers)
    return {
        key: sanitized[key]
        for key in sorted(sanitized)
        if key in interesting_headers
    }


def build_auth_log_context(
    *,
    request_id: str,
    runtime_profile: RuntimeProfile,
    auth_protocol: AuthProtocol,
    actor: ActorContext | None = None,
) -> dict[str, str | bool | None]:
    """Return a minimal, redacted structured log context."""
    return {
        "request_id": request_id,
        "actor_id": actor.id if actor else None,
        "runtime_profile": runtime_profile.value,
        "auth_protocol": auth_protocol.value,
        "authenticated": actor is not None,
    }


def build_auth_log_event(
    *,
    auth_log_context: Mapping[str, str | bool | None],
    method: str,
    path: str,
    status_code: int,
    deny_reason: str | None,
    headers: Mapping[str, str],
) -> dict[str, object]:
    """Return the emitted structured auth event payload."""
    event: dict[str, object] = dict(auth_log_context)
    event.update(
        {
            "method": method,
            "path": path,
            "status_code": status_code,
            "headers": dict(headers),
        }
    )
    if deny_reason is not None:
        event["deny_reason"] = deny_reason
    return event
