"""FastAPI auth dependencies for REQ-002."""

from __future__ import annotations

from typing import Iterable
from uuid import uuid4

from fastapi import Depends, HTTPException, Request, status

from backend.shared.authz.claims import AuthenticationRequiredError, parse_actor_from_headers
from backend.shared.authz.logging import build_auth_log_context
from backend.shared.authz.models import ActorContext, Permission
from backend.shared.authz.settings import AuthSettings, load_auth_settings


def get_auth_settings(request: Request) -> AuthSettings:
    app_settings = getattr(request.app.state, "auth_settings", None)
    if isinstance(app_settings, AuthSettings):
        return app_settings
    return load_auth_settings()


async def get_current_actor(
    request: Request,
    settings: AuthSettings = Depends(get_auth_settings),
) -> ActorContext:
    request_id = request.headers.get(settings.request_id_header) or str(uuid4())

    try:
        actor = parse_actor_from_headers(request.headers, settings)
    except AuthenticationRequiredError as exc:
        request.state.request_id = request_id
        request.state.auth_denied_reason = "authentication_required"
        request.state.auth_log_context = build_auth_log_context(
            request_id=request_id,
            runtime_profile=settings.runtime_profile,
            auth_protocol=settings.auth_protocol,
            actor=None,
        )
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail="authentication_required",
        ) from exc

    request.state.request_id = request_id
    request.state.actor = actor
    request.state.auth_log_context = build_auth_log_context(
        request_id=request_id,
        runtime_profile=settings.runtime_profile,
        auth_protocol=settings.auth_protocol,
        actor=actor,
    )

    if not actor.active:
        request.state.auth_denied_reason = "forbidden"
        raise HTTPException(
            status_code=status.HTTP_403_FORBIDDEN,
            detail="forbidden",
        )

    request.state.auth_denied_reason = None
    return actor


def require_permissions(*required_permissions: Permission | str):
    normalized_required = frozenset(_normalize_permissions(required_permissions))

    async def dependency(
        request: Request,
        actor: ActorContext = Depends(get_current_actor),
    ) -> ActorContext:
        if not normalized_required.issubset(actor.permissions):
            request.state.auth_denied_reason = "forbidden"
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail="forbidden",
            )
        return actor

    return dependency


def _normalize_permissions(required_permissions: Iterable[Permission | str]) -> set[str]:
    normalized: set[str] = set()
    for permission in required_permissions:
        if isinstance(permission, Permission):
            normalized.add(permission.value)
        else:
            normalized.add(str(permission))
    return normalized
