from __future__ import annotations

import logging

import pytest
from fastapi.testclient import TestClient

from backend.shared.authz.claims import normalize_identity_claims
from backend.shared.authz.logging import build_auth_log_context, build_header_snapshot, sanitize_headers
from backend.shared.authz.models import ActorContext, AuthProtocol, Permission, RuntimeProfile
from backend.shared.authz.settings import AuthSettings


def test_normalize_identity_claims_is_deterministic_for_oidc_and_saml_shapes(
    settings: AuthSettings,
) -> None:
    oidc_actor = normalize_identity_claims(
        {
            "sub": "oidc-user-1",
            "preferred_username": "mario.rossi",
            "name": "Mario Rossi",
            "groups": ["operators", "exporters"],
            "permissions": ["unknown.permission", Permission.DOCUMENT_AI_QUERY.value],
        },
        settings,
    )
    assert oidc_actor.id == "oidc-user-1"
    assert oidc_actor.username == "mario.rossi"
    assert oidc_actor.display_name == "Mario Rossi"
    assert Permission.DOCUMENT_UPLOAD.value in oidc_actor.permissions
    assert Permission.DOCUMENT_EXPORT.value in oidc_actor.permissions
    assert Permission.DOCUMENT_AI_QUERY.value in oidc_actor.permissions
    assert "unknown.permission" not in oidc_actor.permissions

    saml_actor = normalize_identity_claims(
        {
            "name_id": "saml-user-7",
            "display_name": "Giulia Bianchi",
            "roles": ["reviewers", "ai-users"],
            "active": "true",
        },
        settings,
    )
    assert saml_actor.id == "saml-user-7"
    assert saml_actor.display_name == "Giulia Bianchi"
    assert Permission.DOCUMENT_VALIDATE.value in saml_actor.permissions
    assert Permission.DOCUMENT_AI_QUERY.value in saml_actor.permissions


def test_sensitive_auth_headers_are_redacted_and_log_context_is_minimal(settings: AuthSettings) -> None:
    sanitized = sanitize_headers(
        {
            "Authorization": "Bearer secret-token",
            "X-Zen-Auth-Claims": '{"sub":"user-1"}',
            "X-Request-Id": "req-002-log-1",
        },
        settings.resolved_sensitive_headers,
    )

    assert sanitized["authorization"] == "[REDACTED]"
    assert sanitized["x-zen-auth-claims"] == "[REDACTED]"
    assert sanitized["x-request-id"] == "req-002-log-1"

    actor = ActorContext(
        id="user-1",
        username="mario.rossi",
        display_name="Mario Rossi",
        permissions=frozenset({Permission.DOCUMENT_UPLOAD.value}),
        groups=frozenset({"operators"}),
    )
    context = build_auth_log_context(
        request_id="req-002-log-1",
        runtime_profile=RuntimeProfile.LOCAL,
        auth_protocol=AuthProtocol.OIDC,
        actor=actor,
    )

    assert context == {
        "request_id": "req-002-log-1",
        "actor_id": "user-1",
        "runtime_profile": "local",
        "auth_protocol": "oidc",
        "authenticated": True,
    }


